def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    recent = history[-10:] if n >= 10 else history
    opp_c_recent = sum(1 for _, o in recent if o == 'C')
    total_opp_c = sum(1 for _, o in history if o == 'C')

    opp_d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    md_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            md_streak += 1
        else:
            break

    after_d_total = 0
    after_d_c = 0
    unprovoked_d = 0
    if n > 1:
        prev_me = history[0][0]
        for i in range(1, n):
            cur_opp = history[i][1]
            if prev_me == 'C':
                if cur_opp == 'D':
                    unprovoked_d += 1
            else:
                after_d_total += 1
                if cur_opp == 'C':
                    after_d_c += 1
            prev_me = history[i][0]

    if after_d_total > 0:
        resp_d = after_d_c / after_d_total
    else:
        resp_d = 0.5

    coop_signal = opp_c_recent >= 4 or total_opp_c * 2 >= n
    chronic = (
        (opp_c_recent <= 1 and n >= 10) or
        (total_opp_c <= 1 and n >= 8) or
        (opp_d_streak >= 12 and opp_c_recent <= 3)
    )

    if chronic:
        return 'D'

    forgiving = after_d_total >= 2 and resp_d >= 0.7 and opp_c_recent >= 5

    if n >= 95:
        if last_opp == 'D':
            return 'D'
        if forgiving:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if unprovoked_d >= 4 and opp_c_recent >= 6:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    if last_opp == 'D':
        if forgiving and opp_d_streak <= 3:
            return 'D'
        if last_me == 'C':
            if opp_d_streak <= 4 and coop_signal:
                return 'C'
            return 'D'
        if opp_c_recent <= 2 or opp_d_streak >= 8:
            return 'D'
        if md_streak >= 2 and opp_d_streak <= 6 and coop_signal:
            return 'C'
        return 'D'

    if forgiving:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    if unprovoked_d >= 4 and opp_c_recent >= 6:
        prob = 0.02
        if after_d_total >= 1 and resp_d >= 0.7:
            prob += 0.08
        if after_d_total >= 2 and resp_d >= 0.7:
            prob += 0.08
        if opp_c_recent >= 8:
            prob += 0.05
        if rng.random() < prob:
            return 'D'

    return 'C'
